'use client';

import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';

type Role = 'Admin' | 'Instructor' | 'Student';

interface Department {
  id: number;
  code: string;
  name: string;
}

interface UserRow {
  id: number;
  employee_id: string | null;
  student_id: string | null;
  email: string;
  first_name: string;
  last_name: string;
  dept_id: number | null;
  department?: Department;
  role: Role;
  is_irregular: boolean;
  is_active: boolean;
  created_at: string;
}

interface UsersResponse {
  success: boolean;
  message: string;
  data: { data: UserRow[] } | UserRow[];
  meta?: { total?: number; page?: number; per_page?: number };
}

const ROLE_BADGE: Record<Role, { bg: string; color: string; dot: string }> = {
  Admin: { bg: '#eef2ff', color: '#3730a3', dot: '#6366f1' },
  Instructor: { bg: '#fff8e6', color: '#92620a', dot: '#f0a500' },
  Student: { bg: '#e8f5ee', color: '#1a7a3c', dot: '#22a050' },
};

const initials = (f: string, l: string) => `${f[0] ?? ''}${l[0] ?? ''}`.toUpperCase();
const fmtDate = (iso: string) =>
  new Date(iso).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });

function StatCard({ label, value, color }: { label: string; value: number; color: string }) {
  return (
    <div className="card flex flex-col gap-1" style={{ padding: '14px 18px', borderLeft: `3px solid ${color}` }}>
      <span className="text-[22px] font-bold leading-none" style={{ color }}>{value}</span>
      <span className="text-[11px] uppercase tracking-wider font-medium" style={{ color: 'var(--color-text-muted)' }}>
        {label}
      </span>
    </div>
  );
}

function RoleBadge({ role }: { role: Role }) {
  const s = ROLE_BADGE[role];
  return (
    <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[11px] font-semibold" style={{ background: s.bg, color: s.color }}>
      <span className="w-1.5 h-1.5 rounded-full" style={{ background: s.dot }} />
      {role}
    </span>
  );
}

export default function AdminUsersPage() {
  const [users, setUsers] = useState<UserRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState<Role | 'All'>('All');
  const [deptFilter, setDeptFilter] = useState<number | 'All'>('All');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Active' | 'Inactive'>('All');
  const [currentPage, setCurrentPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [perPage, setPerPage] = useState(15);
  const [actionLoadingId, setActionLoadingId] = useState<number | null>(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await api.get<UsersResponse>(`/admin/users?page=${currentPage}`);
        if (!mounted) return;

        const payload = response.data;
        const rows = Array.isArray(payload) ? payload : payload.data;
        setUsers(rows ?? []);
        setTotal(response.meta?.total ?? (rows?.length ?? 0));
        setPerPage(response.meta?.per_page ?? 15);
      } catch (e) {
        if (!mounted) return;
        setError(e instanceof Error ? e.message : 'Failed to load users.');
      } finally {
        if (mounted) setLoading(false);
      }
    })();

    return () => {
      mounted = false;
    };
  }, [currentPage]);

  const departments = useMemo(() => {
    const map = new Map<number, Department>();
    users.forEach((u) => {
      if (u.department?.id) map.set(u.department.id, u.department);
    });
    return Array.from(map.values()).sort((a, b) => a.code.localeCompare(b.code));
  }, [users]);

  const stats = useMemo(() => ({
    total,
    admins: users.filter((u) => u.role === 'Admin').length,
    instructors: users.filter((u) => u.role === 'Instructor').length,
    students: users.filter((u) => u.role === 'Student').length,
    active: users.filter((u) => u.is_active).length,
    inactive: users.filter((u) => !u.is_active).length,
  }), [users, total]);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return users.filter((u) => {
      if (roleFilter !== 'All' && u.role !== roleFilter) return false;
      if (deptFilter !== 'All' && u.dept_id !== deptFilter) return false;
      if (statusFilter === 'Active' && !u.is_active) return false;
      if (statusFilter === 'Inactive' && u.is_active) return false;
      if (q && !`${u.first_name} ${u.last_name} ${u.email} ${u.employee_id ?? ''} ${u.student_id ?? ''}`.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [users, search, roleFilter, deptFilter, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(total / perPage));
  const hasFilters = search || roleFilter !== 'All' || deptFilter !== 'All' || statusFilter !== 'All';

  const reset = () => {
    setSearch('');
    setRoleFilter('All');
    setDeptFilter('All');
    setStatusFilter('All');
  };

  const handleToggleActive = async (user: UserRow) => {
    try {
      setActionLoadingId(user.id);
      setError(null);
      if (user.is_active) {
        await api.post(`/admin/users/${user.id}/deactivate`, {});
      } else {
        await api.post(`/admin/users/${user.id}/reactivate`, {});
      }
      setUsers((prev) => prev.map((u) => (u.id === user.id ? { ...u, is_active: !u.is_active } : u)));
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update user status.');
    } finally {
      setActionLoadingId(null);
    }
  };

  return (
    <AppShell role="admin" userName="Admin" pageTitle="User Management">
      <div className="animate-fade-in">
        <div className="flex items-start justify-between gap-4 mb-5 flex-wrap">
          <div>
            <h1 className="text-[20px] font-bold" style={{ color: 'var(--color-text)' }}>User Management</h1>
            <p className="text-[13px] mt-0.5" style={{ color: 'var(--color-text-muted)' }}>
              Manage all Admins, Instructors, and Students on the platform.
            </p>
          </div>
          <Link href="/admin/users/create" className="btn btn-primary flex items-center gap-2 text-[13px] shrink-0" style={{ padding: '9px 18px' }}>
            Create User
          </Link>
        </div>

        {error && (
          <div className="mb-4 rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: '#fecaca', background: '#fff1f2', color: '#9f1239' }}>
            {error}
          </div>
        )}

        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 mb-5">
          <StatCard label="Total" value={stats.total} color="var(--color-text-secondary)" />
          <StatCard label="Admins" value={stats.admins} color="#3730a3" />
          <StatCard label="Instructors" value={stats.instructors} color="#92620a" />
          <StatCard label="Students" value={stats.students} color="#1a7a3c" />
          <StatCard label="Active" value={stats.active} color="var(--color-success)" />
          <StatCard label="Inactive" value={stats.inactive} color="var(--color-error)" />
        </div>

        <div className="card card-body mb-4 flex flex-col md:flex-row flex-wrap gap-3 md:items-center" style={{ padding: '14px 18px' }}>
          <div className="relative w-full md:flex-1" style={{ minWidth: '200px' }}>
            <input
              type="search"
              placeholder="Search by name, email, or ID..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full rounded border border-gray-300"
              style={{ paddingLeft: '0.75rem', fontSize: '13px', height: '38px' }}
            />
          </div>

          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            <select
              className="w-full sm:w-auto rounded border border-gray-300 px-2"
              value={roleFilter}
              onChange={(e) => setRoleFilter(e.target.value as Role | 'All')}
              style={{ fontSize: '13px', height: '38px' }}
            >
              <option value="All">All Roles</option>
              <option value="Admin">Admin</option>
              <option value="Instructor">Instructor</option>
              <option value="Student">Student</option>
            </select>

            <select
              className="w-full sm:w-auto rounded border border-gray-300 px-2"
              value={deptFilter}
              onChange={(e) => setDeptFilter(e.target.value === 'All' ? 'All' : Number(e.target.value))}
              style={{ fontSize: '13px', height: '38px', maxWidth: '200px' }}
            >
              <option value="All">All Departments</option>
              {departments.map((d) => <option key={d.id} value={d.id}>{d.code} - {d.name}</option>)}
            </select>

            <select
              className="w-full sm:w-auto rounded border border-gray-300 px-2"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as 'All' | 'Active' | 'Inactive')}
              style={{ fontSize: '13px', height: '38px' }}
            >
              <option value="All">All Status</option>
              <option value="Active">Active</option>
              <option value="Inactive">Inactive</option>
            </select>

            {hasFilters && (
              <button
                onClick={reset}
                className="flex items-center gap-1 text-[12.5px] font-medium transition-colors w-full sm:w-auto justify-center sm:justify-start"
                style={{ color: 'var(--color-error)', background: 'none', border: 'none' }}
              >
                Clear
              </button>
            )}
          </div>
        </div>

        <div className="card overflow-hidden mb-3">
          <div className="overflow-x-auto">
            <table className="table-base">
              <thead>
                <tr>
                  <th>User</th>
                  <th>Role</th>
                  <th>Department</th>
                  <th>ID</th>
                  <th>Status</th>
                  <th>Created</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr>
                    <td colSpan={7} className="text-center py-10 text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
                      Loading users...
                    </td>
                  </tr>
                ) : filtered.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="text-center py-16 text-[13px]" style={{ color: 'var(--color-text-muted)' }}>
                      No users match your filters.
                    </td>
                  </tr>
                ) : filtered.map((user) => {
                  const idLabel = user.role === 'Student' ? user.student_id : user.employee_id;
                  return (
                    <tr key={user.id} className="group">
                      <td>
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0 text-[11px] font-bold" style={{ background: 'var(--color-primary)', color: '#fff' }}>
                            {initials(user.first_name, user.last_name)}
                          </div>
                          <div>
                            <p className="text-[12.5px] font-semibold" style={{ color: 'var(--color-text)' }}>
                              {user.last_name}, {user.first_name}
                            </p>
                            <p className="text-[11.5px]" style={{ color: 'var(--color-text-muted)' }}>{user.email}</p>
                          </div>
                        </div>
                      </td>
                      <td><RoleBadge role={user.role} /></td>
                      <td>
                        <span className="font-mono text-[11.5px] px-2 py-0.5 rounded-md" style={{ background: 'var(--color-surface-2)', color: 'var(--color-text-secondary)' }}>
                          {user.department?.code ?? '-'}
                        </span>
                      </td>
                      <td className="font-mono text-[12px]" style={{ color: 'var(--color-text-secondary)' }}>{idLabel ?? '-'}</td>
                      <td>
                        <button
                          type="button"
                          onClick={() => handleToggleActive(user)}
                          disabled={actionLoadingId === user.id}
                          className="inline-flex items-center gap-1.5 text-[12px] font-semibold disabled:opacity-60"
                          style={{ color: user.is_active ? 'var(--color-success)' : 'var(--color-error)' }}
                        >
                          <span className="w-1.5 h-1.5 rounded-full" style={{ background: user.is_active ? 'var(--color-success)' : 'var(--color-error)' }} />
                          {actionLoadingId === user.id ? 'Updating...' : user.is_active ? 'Active' : 'Inactive'}
                        </button>
                      </td>
                      <td className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>{fmtDate(user.created_at)}</td>
                      <td style={{ textAlign: 'right' }}>
                        <Link href={`/admin/users/${user.id}`} className="inline-flex items-center gap-1 text-[12px] font-medium transition-colors" style={{ color: 'var(--color-primary-light)' }}>
                          View
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {totalPages > 1 && (
            <div className="border-t flex items-center justify-between px-5 py-3" style={{ borderColor: 'var(--color-border)' }}>
              <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
                Showing page {currentPage} of {totalPages}
              </p>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="px-2 py-1 rounded border text-[12px] disabled:opacity-40"
                  style={{ borderColor: 'var(--color-border)' }}
                >
                  Prev
                </button>
                <button
                  onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                  disabled={currentPage === totalPages}
                  className="px-2 py-1 rounded border text-[12px] disabled:opacity-40"
                  style={{ borderColor: 'var(--color-border)' }}
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppShell>
  );
}
